from collections import Counter
from common import *

def main():
    result=get(D/"results.json");groups=result["groups"];full=groups["all"]
    sign=get(D/"answer-seal.json");receipt=get(D/"source-seal.json")
    ins=get(D/"input-seal.json");n=result["denominators"]["all"]
    contexts=get(D/"contexts.json.gz");pred=get(D/"answers.json.gz")
    def num(x):return f"{x:.2f}".replace(".",",")
    def estimate(group,contrast="true-lex",axis=1,interval="cluster_ci"):
        t=groups[group]["contrasts"][contrast]
        d=t["pp"][axis];a,b=t[interval][axis]
        return f"{num(d)} [{num(a)}; {num(b)}]"
    s=full["means"];means=lambda arm,axis:num(s[arm][axis]*100)
    primary=full["contrasts"]["true-lex"];swapped=result["denominators"]["switched"]
    lines=["# Перенос Qwen и выбора по наблюдаемому упоминанию на MuSiQue-Ans dev","",
        f'На всех {n:,} вопросах подлинный переход дал **{means("true",1)} Answer F1**, лексическое расширение — **{means("lex",1)}**. Парная разность составила **{estimate("all")} п.п.** по {result["clusters"]} кластерам первого документа. У пяти сопоставленных переназначений упоминания средний F1 равен {means("sham",1)}. Подлинный переход минус переназначение — **{estimate("all","true-sham")} п.п.**'.replace("2,417","2 417"),"",
        "| Второй документ | EM, % | Answer F1 | Все эталонные ID среди двух выбранных, % | Ответ или алиас в доставленном тексте, % |",
        "|---|---:|---:|---:|---:|"]
    for key,name in [("true","Наблюдаемое упоминание и расширенный лексический ранг"),("lex","Расширенный лексический ранг"),("sham","Переназначение наблюдаемых рёбер, среднее пяти семян")]:
        lines.append("| "+name+" | "+" | ".join(means(key,j) for j in range(4))+" |")
    lines.extend(["","Обе политики сначала выбирают один и тот же абзац по BM25 на заголовках. Лексический контроль объединяет ранги заголовков по вопросу и первым 192 WordPiece прочитанного абзаца. Подлинный переход приоритетно выбирает заголовок, последовательность слов которого встретилась в этом абзаце, и использует тот же объединённый ранг. Для контроля placebo адреса упоминаний переназначены при сохранении количества и позиций, с предпочтением адресов с близкими рангами и длиной заголовка.","",
        f'В основном сравнении F1 вырос на {primary["wins"][1]} вопросах, снизился на {primary["losses"][1]}, остался равным на {n-primary["wins"][1]-primary["losses"][1]}. Парная разность по EM равна {estimate("all",axis=0)} п.п. По всем вопросам контроль placebo минус лексический даёт {estimate("all","sham-lex")} п.п. F1. При повторном выборе также пяти семян интервал контраста подлинного с placebo составляет {estimate("all","true-sham",interval="cluster_seed_ci")} п.п. Пять индивидуальных разностей F1 равны '+", ".join(num(z[1]) for z in full["contrasts"]["true-sham"]["per_seed"])+". [Полные результаты](./results.json)","",
        "### Что даёт ссылка на конкретный заголовок","",
        f'Из {n} вопросов в {swapped} ({num(100*swapped/n)}%) подлинное упоминание изменило второй ID. Все 5 × {swapped} placebo-переходов действительно пошли к другому, не отмеченному упоминанием адресу, сохранив число и позиции связей и сам факт переключения. Для {n-swapped} вопросов подлинный и лексический режимы использовали одинаковый адрес. Число различных полных входов в этом основном сравнении на уровне вопроса составило {result["primary_different_sequences"]}.',"",
        "| Подгруппа | Вопросы | Кластеры первого документа | F1 подлинный | F1 лексический | Парная разность F1, п.п. [95%] |",
        "|---|---:|---:|---:|---:|---:|"])
    for key,name in [("switched","Второй ID изменился"),("unchanged","Второй ID совпал"),("hops_2","Две эталонные опоры"),("hops_3","Три опоры"),("hops_4","Четыре опоры"),("seen_r46_False","Первый документ отсутствовал в прежней панели train"),("seen_r46_True","Первый документ встречался в прежней панели"),("no_any_r46","Весь каталог без пересечения с прежней панелью"),("no_any_train","Весь каталог без пересечения с полным train")]:
        g=groups[key];lines.append(f'| {name} | {g["n"]} | {g["contrasts"]["true-lex"]["clusters"]} | {num(100*g["means"]["true"][1])} | {num(100*g["means"]["lex"][1])} | {estimate(key)} |')
    stops=Counter(r["stop"] for r in pred.values())
    lines+=["",f'Это описательные срезы. Для переключившихся вопросов подлинный переход минус placebo составил {estimate("switched","true-sham")} п.п. F1. Предварительно заданный основной знаменатель включает неизменившиеся и многошаговые вопросы. Полнота всех адресов для трёх и четырёх опор ограничена бюджетом двух документов. [Порядки и переназначения](./orders.json.gz) · [Построчные исходы](./outcomes.json.gz)',"",
        "### Происхождение и исполнение","",
        f'Авторские dev и train из официального архива побайтно совпали с независимыми локальными копиями. В 2 417 dev-записях {receipt["dev_unique_forms"]} различных нормализованных вопросов и {receipt["dev_unique_docs"]} различных документов. Пересечение нормализованных вопросов или ID с 19 938 записями train равно нулю. С полным train совпали 3 697 точных абзацев, с прежней панелью из 1 024 — 791. Хотя бы одно совпадение во всём каталоге есть у 2 250 и 1 066 вопросов соответственно. R32 оценивал на всех этих dev-вопросах retrieval, R33 — ответы DistilBERT с другими сравнениями. Данный опыт переносит на dev генеративный Qwen из R46/R47. Возможное попадание материала в предобучение Qwen определить нельзя. [Архив авторов](https://github.com/StonyBrookNLP/musique) · [Хеши и пересечения](./source-seal.json)',"",
        f'У всех семи ветвей внутри каждого вопроса фактическое число входных токенов совпало. Среднее — {num(result["mean_input"])}, минимум — {result["min_input"]}, максимум — {result["max_input"]}. Из-за ограничения самым коротким вторым фрагментом одна из новых ветвей уменьшила общий предел относительно R46 в {result["common_shortened"]} вопросах. В одной и той же Qwen3-4B-Instruct-2507 Q4_K_M выставлены максимум 96 выходных токенов и остановка на первой новой строке. {ins["logical"]} логических ответов потребовали {ins["unique"]} различных новых вызовов. Среди 32 повторов изменилось {sign["different"]}; время генерации с повторами — {num(sign["seconds"])} с. Зарегистрированные причины остановки среди уникальных прогнозов: '+", ".join(f'{k} {v}' for k,v in sorted(stops.items()))+'. Это оценка зафиксированного двухдокументного интерфейса, одного ридера и одной версии MuSiQue. [Зафиксированные ответы](./answers.json.gz) · [Протокол](./PROTOCOL_RU.md) · [Воспроизведение](./REPRODUCE_RU.md)']
    (D/"REPORT_RU.md").write_bytes(("\n".join(lines)+"\n").encode())
if __name__=="__main__":main()
